select (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'song_text_backups') as columnas, (select relrowsecurity from pg_class where oid = 'public.song_text_backups'::regclass) as rls_activa, (select count(*) from pg_policies where schemaname = 'public' and tablename = 'song_text_backups') as politicas, (select column_default from information_schema.columns where table_schema = 'public' and table_name = 'song_text_backups' and column_name = 'organization_id') as default_organization, (select count(*) from public.song_text_backups) as filas
